174	// HandleGroupDetected incorporates one detection result into the ordered entry list.
175	// When all detections have completed it finalizes entries and switches to input state.
176	func (b *RegistryBrowser) HandleGroupDetected(msg RegistryGroupDetectedMsg) (*RegistryBrowser, tea.Cmd) {
177		for i, reg := range b.registries {
178			if reg.URL != msg.RegistryURL {
179				continue
180			}
181			alias := reg.Alias
182			if alias == "" {
183				alias = reg.URL
184			}
185			if len(msg.Members) > 0 {
186				group := make([]browserRegistryEntry, len(msg.Members))
187				for j, m := range msg.Members {
188					group[j] = browserRegistryEntry{
189						URL:         m.URL,
190						Alias:       m.Alias,
191						ParentAlias: alias,
192						parentURL:   reg.URL,
193					}
194				}
195				b.entryGroups[i] = group
196			} else {
197				b.entryGroups[i] = []browserRegistryEntry{{URL: reg.URL, Alias: alias}}
198			}
199			break
200		}
201		b.pendingDetections--
202		if b.pendingDetections <= 0 {
203			b.finalizeEntries()
204		}
205		return b, nil
206	}
