670	// normalizeRepoForRegistry prepends "library/" for bare names on Docker Hub.
671	func normalizeRepoForRegistry(registryURL, repo string) string {
672		if strings.Contains(repo, "/") {
673			return repo
674		}
675		base := strings.ToLower(strings.TrimSuffix(registryURL, "/"))
676		for _, alias := range []string{"docker.io", "registry-1.docker.io"} {
677			if base == alias {
678				return "library/" + repo
679			}
680		}
681		return repo
682	}
683	
684	// multiImageName constructs the full image reference for pull/scan.
685	func multiImageName(registryURL, repo, tag string) string {
686		base := strings.TrimSuffix(registryURL, "/")
687		for _, alias := range []string{"docker.io", "registry-1.docker.io"} {
688			if strings.EqualFold(base, alias) {
689				return repo + ":" + tag
690			}
691		}
692		return base + "/" + repo + ":" + tag
693	}
