513				LastUpdated string `json:"last_updated"`
514			} `json:"results"`
515		}
516		if err := json.Unmarshal(body, &result); err != nil {
517			return nil, err
518		}
519		meta := make(map[string]time.Time, len(result.Results))
520		for _, r := range result.Results {
521			if t, err := time.Parse(time.RFC3339Nano, r.LastUpdated); err == nil {
522				meta[r.Name] = t
523			}
524		}
