567			}
568			if password == "" {
569				password = storedPass
570			}
571	
572			// When a ManagementURL is set, its host may differ from the Docker registry
573			// host. Docker stores credentials by hostname only, so extract just the
574			// scheme+host (strip the repository path) before looking up credentials.
575			if reg.ManagementURL != "" && password == "" {
576				mgmtLookup := reg.ManagementURL
577				if u, err := url.Parse(reg.ManagementURL); err == nil && u.Host != "" {
