	m.currentField++
	if m.currentField > 4 {
		m.currentField = 4
	}

	m.updateFocus()
}

// prevField passe au champ précédent
func (m *Model) prevField() {
	m.currentField--
	if m.currentField < 0 {
		m.currentField = 0
	}

	m.updateFocus()
}

// updateFocus met à jour le focus des champs
func (m *Model) updateFocus() {
	switch m.currentField {
	case 0:
		m.urlInput.Focus()
		m.tokenInput.Blur()
	case 1:
		m.urlInput.Blur()
		m.tokenInput.Focus()
	default:
		// Champs 2, 3, 4 (checkboxes et button) - pas de textinput
		m.urlInput.Blur()
		m.tokenInput.Blur()
	}
}

