3	import (
4		"fmt"
5		"strings"
6	)
7	
8	// DiagResult holds the output and success status of a diagnostic command
9	type DiagResult struct {
10		Success bool
11		Output  string
12	}
13	
14	// runDiagHost runs a command in an ephemeral container with --network host
15	func runDiagHost(image string, args []string) DiagResult {
16		if runner.LookPath() != nil {
17			return DiagResult{false, "docker not found"}
18		}
19		cmdArgs := append([]string{"run", "--rm", "--network", "host", image}, args...)
20		output, err := dockerCombined(cmdArgs...)
21		out := strings.ReplaceAll(string(output), "\r\n", "\n")
22		out = strings.ReplaceAll(out, "\r", "\n")
23		out = strings.TrimSpace(out)
24		return DiagResult{err == nil, out}
25	}
26	
27	// RunPing executes ping -c 3 <target> in the network multitool container
28	func RunPing(image, target string) DiagResult {
29		return runDiagHost(image, []string{"ping", "-c", "3", target})
30	}
31	
32	// RunDNS executes dig <target> [@dnsServer] in the network multitool container.
33	// If dnsServer is empty, the container's default resolver is used.
34	func RunDNS(image, target, dnsServer string) DiagResult {
35		args := []string{"dig", target}
36		if strings.TrimSpace(dnsServer) != "" {
37			args = append(args, "@"+strings.TrimSpace(dnsServer))
38		}
39		return runDiagHost(image, args)
40	}
41	
42	// RunReverseDNS executes dig -x <ip> [@dnsServer] for PTR (reverse DNS) lookup.
43	// If dnsServer is empty, the container's default resolver is used.
44	func RunReverseDNS(image, ip, dnsServer string) DiagResult {
45		args := []string{"dig", "-x", ip}
46		if strings.TrimSpace(dnsServer) != "" {
47			args = append(args, "@"+strings.TrimSpace(dnsServer))
48		}
49		return runDiagHost(image, args)
50	}
51	
52	// RunTraceroute executes traceroute -m 30 -w 1 <target> in the network tool container
53	func RunTraceroute(image, target string) DiagResult {
54		return runDiagHost(image, []string{"traceroute", "-m", "30", "-w", "1", target})
55	}
56	
57	// RunTCPTraceroute executes tcptraceroute -m 30 -w 1 <target> <port> in the network tool container.
58	// The exit code is ignored: tcptraceroute returns non-zero when the destination is not reached within
59	// the hop limit, but the partial trace is still useful output.
60	func RunTCPTraceroute(image, target, port string) DiagResult {
61		if runner.LookPath() != nil {
62			return DiagResult{false, "docker not found"}
63		}
64		args := []string{"run", "--rm", "--network", "host", image, "tcptraceroute", "-m", "30", "-w", "1", target, port}
65		output, _ := dockerCombined(args...)
66		out := strings.ReplaceAll(string(output), "\r\n", "\n")
67		out = strings.ReplaceAll(out, "\r", "\n")
68		out = strings.TrimSpace(out)
69		return DiagResult{out != "", out}
70	}
71	
72	// RunNetcat executes nc -zv -w 2 <target> <port> in the network multitool container
73	func RunNetcat(image, target, port string) DiagResult {
74		return runDiagHost(image, []string{"nc", "-zv", "-w", "2", target, port})
75	}
76	
77	// RunCurl executes curl against the target, trying HTTPS then HTTP if port is 443 or 80 respectively
78	func RunCurl(image, target, port string) DiagResult {
79		scheme := "http"
80		if port == "443" {
81			scheme = "https"
82		}
83		url := fmt.Sprintf("%s://%s:%s", scheme, target, port)
84		return runDiagHost(image, []string{"curl", "-sS", "-I", "--max-time", "3", url})
85	}
86	
87	// sslCertScript extracts the issuer, subject and expiry of the certificate served
88	// by "$1:$2". The target and port are read from the positional parameters and are
89	// never interpolated into the script text — see RunSSLCert.
90	const sslCertScript = `echo | openssl s_client -showcerts -servername "$1" -connect "$1:$2" 2>/dev/null | ` +
91		`openssl x509 -inform pem -noout -text | grep "Issuer\|Subject\|Not After"`
92	
93	// RunSSLCert checks the SSL certificate details for the target:port.
94	//
95	// The pipeline requires a shell, so target and port are passed as positional
96	// arguments ("sh -c <script> sh <target> <port>") rather than being formatted
97	// into the script. This keeps them as argv values that the shell never parses,
98	// so a target such as `example.com; rm -rf /` cannot break out of the script.
99	func RunSSLCert(image, target, port string) DiagResult {
100		return runDiagHost(image, []string{"/bin/sh", "-c", sslCertScript, "sh", target, port})
101	}
