89	// buildDNSTestCmd builds the DNS or reverse DNS test command depending on the target.
90	// If the target is an IP address, it uses dig -x for PTR lookup and relabels the result row.
91	func (m *Model) buildDNSTestCmd(gen int, target, dnsServer, image string) tea.Cmd {
92		effectiveName := "DNS Resolution"
93		runner := func() dockerpkg.DiagResult {
94			return dockerpkg.RunDNS(image, target, dnsServer)
95		}
96		if isIPAddress(target) {
97			effectiveName = "Reverse DNS"
98			runner = func() dockerpkg.DiagResult {
99				return dockerpkg.RunReverseDNS(image, target, dnsServer)
100			}
101		}
102		// Rename the key/order entry that was set before the switch in startTests()
103		m.results[effectiveName] = m.results["DNS Resolution"]
104		delete(m.results, "DNS Resolution")
105		m.resultOrder[len(m.resultOrder)-1] = effectiveName
106		return runTestCmd(gen, effectiveName, runner)
107	}
