109	// runTestCmd creates a tea.Cmd that runs fn and returns a testCompleteMsg tagged with gen
110	func runTestCmd(gen int, name string, fn func() dockerpkg.DiagResult) tea.Cmd {
111		return func() tea.Msg {
112			res := fn()
113			return testCompleteMsg{gen: gen, name: name, success: res.Success, output: res.Output}
114		}
115	}
